SELECT

FROM tasks t
WHERE t.id = #{id}
  AND t.delete_flag = ${@com.uit.sociusmvcapp.shared.enums.DeleteFlagEnums@NOT_DELETED.value}

SELECT EXISTS(
    SELECT 1
    FROM tasks
    WHERE id = #{id}
      AND delete_flag = ${@com.uit.sociusmvcapp.shared.enums.DeleteFlagEnums@NOT_DELETED.value}
)

SELECT

FROM tasks t
WHERE t.parent_id = #{parentId}
  AND t.delete_flag = ${@com.uit.sociusmvcapp.shared.enums.DeleteFlagEnums@NOT_DELETED.value}
ORDER BY t.created_at DESC

