SELECT COUNT(*) > 0
FROM tasks
WHERE parent_id = #{taskId}
  AND delete_flag = ${@com.uit.sociusmvcapp.shared.enums.DeleteFlagEnums@NOT_DELETED.value}

SELECT COUNT(*)
FROM tasks
WHERE parent_id = #{parentId}
  AND delete_flag = ${@com.uit.sociusmvcapp.shared.enums.DeleteFlagEnums@NOT_DELETED.value}

SELECT COUNT(*) = 0
FROM tasks
WHERE parent_id = #{parentId}
  AND delete_flag = ${@com.uit.sociusmvcapp.shared.enums.DeleteFlagEnums@NOT_DELETED.value}
  AND status != 2

